const input = $input.first().json;
const body = input.body || input;
const { content_id, practitioner_content_quality, content_calibration } = body;
const quality = practitioner_content_quality || {};
const visual = quality.deterministic_visual || {};
const evidence = quality.evidence_packet || {};
const experiment = (content_calibration || {}).experiment_tags || {};

const supportedRatios = new Set(['1.91:1', '1:1', '4:5', '9:16']);
const blockers = [];
if (!content_id) blockers.push('content_id is required');
if (quality.version !== 'practitioner_evidence_v1') blockers.push('practitioner evidence packet version is required');
if (evidence.status !== 'approved') blockers.push('approved practitioner evidence is required');
if (!Array.isArray(evidence.approved_public_details) || evidence.approved_public_details.length < 2) blockers.push('two approved public details are required');
if (evidence.redaction_receipt?.status !== 'passed') blockers.push('passing redaction receipt is required');
if (visual.system_version !== 'amadutown_deterministic_v1') blockers.push('deterministic visual system version is required');
if (!supportedRatios.has(visual.aspect_ratio)) blockers.push('supported aspect ratio is required');
if (!visual.headline || !Array.isArray(visual.evidence_lines) || visual.evidence_lines.length < 2) blockers.push('headline and evidence lines are required');
if (!visual.visual_rationale) blockers.push('visual rationale is required');
if (!experiment.experiment_id || experiment.causal_claim_boundary !== 'correlational_only') blockers.push('content_calibration experiment tags are required');

return [{ json: {
  success: blockers.length === 0,
  blocked: blockers.length > 0,
  blockers,
  content_id: content_id || null,
  render_contract: blockers.length ? null : {
    renderer: 'portfolio_html_svg',
    system_version: 'amadutown_deterministic_v1',
    template: visual.template,
    aspect_ratio: visual.aspect_ratio,
    typography: { heading: 'Orbitron', body: 'Inter' },
    colors: { navy: '#121E31', gold: '#D4AF37', white: '#EAECEE', slate: '#2C3E50' },
    logo: '/amadutown-logo-upscaled.png',
    safe_area_percent: 6,
    headline: visual.headline,
    eyebrow: visual.eyebrow,
    evidence_lines: visual.evidence_lines,
    result_label: visual.result_label,
    visual_rationale: visual.visual_rationale
  },
  art_direction_receipt: visual.art_direction_receipt || { provider: 'none', model: null, receipt_id: 'workflow-local-deterministic', status: 'not_called' },
  side_effects: { provider_call: false, media_render: false, upload: false, database_write: false, schedule: false, publish: false }
} }];
